11: impl Window {
12:     pub fn new(cap: usize) -> Self {
13:         Window {
14:             buf: vec![0; cap],
15:             cap,
16:             head: 0,
17:             len: 0,
18:             sum: 0,
19:         }
20:     }
21: 
22:     /// Add a reading, evicting the oldest once the window is full.
23:     pub fn push(&mut self, v: i64) {
24:         if self.len == self.cap {
25:             self.sum -= self.buf[self.head];
26:         } else {
27:             self.len += 1;
28:         }
29:         self.buf[self.head] = v;
30:         self.sum += v;
31:         self.head = (self.head + 1) % self.cap;
32:     }
33: 
34:     /// Mean of the readings currently in the window, truncated toward zero.
35:     pub fn mean(&self) -> i64 {
36:         if self.len == 0 {
37:             return 0;
38:         }
39:         self.sum / self.len as i64
40:     }
